请对以下 case 进行三维加权评分。

=== case_id ===
Case-01-low-power-010

=== 用户原始指令 (query.txt) ===
弄个省电模式页面,字写在背景图上,点能跳进应用,红色提示要有

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "弄个省电模式页面,字写在背景图上,点能跳进应用,红色提示要有",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "battery"
      }
    }
  ],
  "dataModel": {
    "value": {
      "power": {
        "title": "低电模式",
        "alert": "电量偏低",
        "hint": "开启省电延长续航",
        "actionText": "进入设置",
        "icon": "resources/base/media/icon_save_power.png"
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "save_power_icon",
      "src": "resources/base/media/icon_save_power.png",
      "use": "power saving background icon",
      "description": "低电/省电场景的省电图标，可作为深色卡片背景上的主视觉锚点。",
      "bindTo": "/power/icon",
      "static": true
    }
  ]
}

